<script setup lang="ts">
import { computed, ref } from 'vue'
import { BookOpen, Check, ChevronRight, Code2, Copy, ExternalLink, Layers3 } from 'lucide-vue-next'
import guideData from './technical-guide-data.json'
type CodeExample={title:string;language:string;code:string;notes:string[];path:string|null;kind:string;url?:string}
type Guide={id:number;title:string;summary:string;flow:string[];terms:{name:string;meaning:string}[];sections:{title:string;paragraphs:string[]}[];codes:CodeExample[];experiments:{action:string;expected:string;reason:string}[];pitfalls:string[];questions:string[];sources:{title:string;url:string}[];status:string;scope:string;reviewed_at:string}
const props=defineProps<{phaseId:number}>()
const guide=computed(()=>(guideData as Guide[]).find(item=>item.id===props.phaseId)!)
const copied=ref(''),copyError=ref('')
async function copyCode(example:CodeExample){
  copyError.value=''
  try{await navigator.clipboard.writeText(example.code);copied.value=`${props.phaseId}:${example.title}`}
  catch{copyError.value='복사할 수 없습니다. 코드 본문을 선택하여 복사하세요.'}
}
const anchor=(part:string)=>`technical-${props.phaseId}-${part}`
</script>

<template>
  <section class="panel technical-guide">
    <div class="panel-heading"><h2><BookOpen :size="18"/> 자세한 기술 학습</h2><span class="small-badge" :class="{'design-label':guide.status==='design'}">{{guide.status==='actual'?'구현 코드 해설':'학습용 설계 예시'}}</span></div>
    <div class="technical-content">
      <h3 class="technical-title">{{guide.title}}</h3><p class="technical-intro">{{guide.summary}}</p>
      <div class="guide-scope"><Code2 :size="17"/><p>{{guide.scope}}</p></div>
      <nav class="guide-jump" aria-label="기술 학습 목차"><a :href="`#${anchor('flow')}`">전체 흐름</a><a :href="`#${anchor('terms')}`">용어</a><a :href="`#${anchor('mechanics')}`">내부 동작</a><a :href="`#${anchor('code')}`">코드 해설</a><a :href="`#${anchor('experiments')}`">실험·예상 결과</a></nav>
      <section :id="anchor('flow')" class="technical-section"><h3><Layers3 :size="17"/> 전체 흐름</h3><ol class="guide-flow"><li v-for="(step,index) in guide.flow" :key="step"><span>{{String(index+1).padStart(2,'0')}}</span><strong>{{step}}</strong><ChevronRight v-if="index<guide.flow.length-1" :size="14"/></li></ol></section>
      <section :id="anchor('terms')" class="technical-section"><h3>먼저 알아둘 용어</h3><dl class="technical-terms"><div v-for="term in guide.terms" :key="term.name"><dt>{{term.name}}</dt><dd>{{term.meaning}}</dd></div></dl></section>
      <section :id="anchor('mechanics')" class="technical-section"><h3>개념에서 구현으로</h3><article v-for="(section,index) in guide.sections" :key="section.title" class="mechanics-section"><h4><span>{{String(index+1).padStart(2,'0')}}</span>{{section.title}}</h4><p v-for="paragraph in section.paragraphs" :key="paragraph">{{paragraph}}</p></article></section>
      <section :id="anchor('code')" class="technical-section"><h3><Code2 :size="17"/> 코드와 함께 읽기</h3><p class="code-reading-note">코드는 설명을 위한 표시입니다. 이 화면에서 실행하지 않습니다. 함수 주변의 연결·인자·imports는 출처 파일이나 예제의 전제를 함께 확인하세요.</p><p v-if="copyError" role="status" class="copy-error">{{copyError}}</p><article v-for="example in guide.codes" :key="example.title" class="guide-code-example"><div class="guide-code-heading"><h4>{{example.title}}</h4><button type="button" class="text-button" :aria-label="`${example.title} 코드 복사`" @click="copyCode(example)"><Check v-if="copied===`${phaseId}:${example.title}`" :size="14"/><Copy v-else :size="14"/>{{copied===`${phaseId}:${example.title}`?'복사됨':'코드 복사'}}</button></div><a v-if="example.url" class="guide-source" :href="example.url" target="_blank" rel="noopener noreferrer">{{example.path}} <ExternalLink :size="12"/></a><span v-else class="guide-source">{{example.language.toUpperCase()}} · 교육용 설계 예시 · 실제 실습 코드와 별도로 읽기</span><pre class="technical-code" tabindex="0" :aria-label="example.title"><code>{{example.code}}</code></pre><ol class="code-walkthrough"><li v-for="note in example.notes" :key="note">{{note}}</li></ol></article></section>
      <section :id="anchor('experiments')" class="technical-section"><h3>실험하면 무엇이 보일까요?</h3><p v-if="guide.status==='design'" class="code-reading-note">아래는 실험 설계와 예상 관찰입니다. 현재 검증 완료된 결과가 아닙니다.</p><div class="guide-table-wrap"><table class="guide-experiments"><thead><tr><th scope="col">변경·동작</th><th scope="col">관찰할 결과</th><th scope="col">기술적 이유</th></tr></thead><tbody><tr v-for="experiment in guide.experiments" :key="experiment.action"><th scope="row">{{experiment.action}}</th><td>{{experiment.expected}}</td><td>{{experiment.reason}}</td></tr></tbody></table></div></section>
      <section class="guide-pitfalls"><h3>이렇게 오해하지 마세요</h3><ul><li v-for="pitfall in guide.pitfalls" :key="pitfall">{{pitfall}}</li></ul></section>
      <section class="technical-section guide-review"><h3>자신의 말로 설명해 보기</h3><ol><li v-for="question in guide.questions" :key="question">{{question}}</li></ol></section>
      <section class="technical-section"><h3>전체 코드와 공식 자료</h3><a v-for="source in guide.sources" :key="source.url" class="guide-reference" :href="source.url" target="_blank" rel="noopener noreferrer">{{source.title}} <ExternalLink :size="13"/></a><p class="code-reading-note">문서 확인: {{guide.reviewed_at}}. 공식 문서의 기본 버전은 설치 버전과 다를 수 있습니다. 예제와 실제 구현·검증 범위를 구분해서 읽으세요.</p></section>
    </div>
  </section>
</template>

