!important;margin:0 0 12px!important;color:#61718a}.code-reading-note{font-size:11px!important;line-height:1.85!important;color:#8794a9!important;margin:12px 0!important}.guide-code-example{margin:20px 0 28px;min-width:0}.guide-code-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.guide-code-heading h4{font-size:13px;margin:0;color:#405a7c}.guide-code-heading button{font-size:11px;white-space:nowrap}.guide-source{display:flex;align-items:center;gap:6px;font:10px monospace;line-height:1.8;color:#8394ac;margin:8px 0;overflow-wrap:anywhere}.technical-code{background:#152239;color:#dce8fb;border-radius:9px;padding:18px;max-width:100%;overflow:auto;white-space:pre;font-size:11px;line-height:1.9;tab-size:4;margin:10px 0 14px}.technical-code:focus-visible{outline:3px solid #8daeff;outline-offset:2px}.code-walkthrough{padding-left:22px;margin:0;font-size:12px;line-height:1.95;color:#62758e}.code-walkthrough li{margin-bottom:8px;padding-left:4px}.guide-table-wrap{overflow:auto;border:1px solid #e4e9f1;border-radius:8px}.guide-experiments{width:100%;border-collapse:collapse;font-size:12px;text-align:left;min-width:480px}.guide-experiments thead{background:#f4f7fc;color:#586f91}.guide-experiments th,.guide-experiments td{padding:13px;vertical-align:top;border-bottom:1px solid #e9edf4;line-height:1.85}.guide-experiments tbody th{font-weight:500;color:#405979;width:30%}.guide-experiments td{color:#6d7f98}.guide-experiments tr:last-child>*{border-bottom:0}.guide-pitfalls{padding:18px;background:#fff8ec;border:1px solid #f1e5cf;border-radius:8px}.guide-pitfalls ul,.guide-review ol{font-size:12px;line-height:1.95;color:#68778d;padding-left:21px;margin:0}.guide-pitfalls li,.guide-review li{margin-bottom:8px}.guide-reference{display:flex;align-items:center;gap:8px;color:#3d6db1;font-size:12px;padding:7px 0}.copy-error{font-size:12px;color:#af4f4f}@media(max-width:900px){.technical-terms>div{grid-template-columns:1fr;gap:5px}}@media(max-width:600px){.technical-content{padding:0 16px 18px}.technical-code{padding:13px;font-size:10px}.guide-flow li{flex-basis:100%}.technical-title{font-size:18px!important}}
